def generate_batch17() -> List[Dict]:
    """生成 batch17 周期化理论 chunks"""
    chunks = []
    for item in PERIODIZATION_DATA:
        chunks.append(make_chunk(
            category="methodology",
            subcategory="periodization",
            title=item["title"],
            content=item["content"],
            keywords=item["keywords"],
        ))
    return chunks


if __name__ == "__main__":
    chunks = generate_batch17()
    print(f"生成 {len(chunks)} 个周期化理论 chunks")

    output_dir = os.path.join(os.path.dirname(__file__), "output")
    os.makedirs(output_dir, exist_ok=True)
    with open(os.path.join(output_dir, "batch17.json"), "w", encoding="utf-8") as f:
        json.dump(chunks, f, ensure_ascii=False, indent=2)
    print(f"已保存到 output/batch17.json")
